mapper.select:
SELECT COUNT(*)
FROM secondhand_subscription
WHERE user_id = #{userId}
  AND status = 'ACTIVE'
  AND keyword = #{keyword}
  AND (
        (category IS NULL AND #{category} IS NULL)
        OR category = #{category}
      )
  AND (
        (max_price IS NULL AND #{maxPrice} IS NULL)
        OR max_price = #{maxPrice}
      )
  AND (
        (campus IS NULL AND #{campus} IS NULL)
        OR campus = #{campus}
      )

SELECT id, user_id, keyword, category, max_price, campus, status, create_time, update_time, last_notified_at
FROM secondhand_subscription

    status = 'ACTIVE'
    AND user_id != #{sellerId}
    AND (
        #{goodsTitle} LIKE CONCAT('%', keyword, '%')
        OR #{goodsDescription} LIKE CONCAT('%', keyword, '%')
    )
    AND (
        category IS NULL OR category = '' OR category = #{goodsCategory}
    )
    AND (
        max_price IS NULL OR max_price >= #{goodsPrice}
    )
    AND (
        campus IS NULL OR campus = '' OR #{sellerCampus} IS NULL OR campus = #{sellerCampus}
    )

ORDER BY create_time DESC
